//! Desktop shell. Commands here are thin adapters: deserialize, call an application
//! service, map errors (ADR-012). Business rules live in `pos-domain` / `pos-application`.

mod commands;
mod error;
mod state;

pub use error::IpcError;
pub use state::AppState;

use pos_local_db::{DbOptions, LocalDb};
use std::path::Path;
use tauri::Manager;

const BINDINGS_HEADER: &str = "// GENERATED by `cargo xtask gen-bindings` from Rust command signatures (ADR-012).\n\
// Do not edit by hand; CI fails if this file is out of date.\n";

/// The typed command registry. Every IPC command must be listed here.
pub fn specta_builder() -> tauri_specta::Builder<tauri::Wry> {
    tauri_specta::Builder::<tauri::Wry>::new().commands(tauri_specta::collect_commands![
        commands::app_info,
        commands::dev_money_add
    ])
}

/// Writes the TypeScript bindings for the command registry.
pub fn export_bindings(path: &Path) -> Result<(), String> {
    specta_builder()
        .export(
            specta_typescript::Typescript::default().header(BINDINGS_HEADER),
            path,
        )
        .map_err(|e| format!("{e:?}"))
}

/// Starts the desktop application.
pub fn run() {
    init_tracing();
    let builder = specta_builder();
    tauri::Builder::default()
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            let dir = app.path().app_data_dir()?;
            // A database failure must not crash the app silently: the UI shows the error
            // (e.g. "update the app" for a newer schema) via `app_info`.
            let db = tauri::async_runtime::block_on(LocalDb::open(&DbOptions::in_dir(&dir)));
            if let Err(e) = &db {
                tracing::error!(error = %e, "local database unavailable");
            }
            app.manage(AppState::new(db.map_err(|e| IpcError::from_error(&e))));
            Ok(())
        })
        .run(tauri::generate_context!())
        .unwrap_or_else(|e| {
            tracing::error!(error = %e, "Sale OS failed to start");
            std::process::exit(1);
        });
}

fn init_tracing() {
    use tracing_subscriber::EnvFilter;
    // E01-T04 replaces this with a rolling JSON file appender plus a redaction layer.
    let _ = tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
        .try_init();
}
